import { MONSTER_DATA } from "@hunt/hunt-data/monarch";
import { type AnswerOption, type QATask } from "@hunt/puzzle-components";

// Flatten MONSTER_DATA to get all monsters across zones
const ALL_PUZZMON_NAMES = Object.values(MONSTER_DATA).flatMap((zone) =>
  Object.values(zone).map((monster) => monster.name),
);

// Helper function from server.ts
function fillTemplate(
  template: string,
  values: Record<string, string>,
): string {
  return template.replace(/{{\s*(\w+)\s*}}/g, (match: string, key: string) => {
    return values[key] !== undefined ? values[key] : match;
  });
}

function toTitleCase(str: string): string {
  return str
    .trim()
    .toLowerCase()
    .replace(/(?:^|[\s-_/]+)\S/g, (match) => match.toUpperCase());
}

// Helper to get answer by ID
function getAnswer(id: string): AnswerOption {
  const answer = PUZZMON_SHOWCASE_TASK.answer_options.find(
    (answer) => answer.id === id,
  );
  if (answer === undefined) {
    throw new Error(`Answer with id ${id} not found.`);
  }
  return answer;
}

// Replicating getBestPuzzmons logic locally
function getBestPuzzmons(
  puzzmonList: string[],
  scoringFunction: (puzzmon: string) => number | bigint | undefined,
): string[] {
  if (puzzmonList.length === 0) {
    return [];
  }
  const scoredPuzzmons = puzzmonList
    .map((puzzmon) => ({
      puzzmon,
      score: scoringFunction(puzzmon),
    }))
    .filter(
      (entry): entry is { puzzmon: string; score: number | bigint } =>
        entry.score !== undefined,
    );
  if (scoredPuzzmons.length === 0) {
    return [];
  }
  const maxScore = scoredPuzzmons.reduce(
    (max, { score }) => (score > max ? score : max),
    scoredPuzzmons[0].score,
  );
  return scoredPuzzmons
    .filter(({ score }) => score === maxScore)
    .map(({ puzzmon }) => puzzmon);
}

export const PUZZMON_SHOWCASE_TASK: QATask = {
  answer_options: [
    {
      id: "zero_one_two_three",
      properties: {},
      task_content: {
        flavor_text: "Showcase Category: Z-E-R-O, O-N-E, T-W-O, T-H-R-E-E, ...",
        scoring_function: (puzzmon: string): number | bigint | undefined => {
          const letterToPoints: Record<string, bigint | undefined> = {
            a: BigInt(1000),
            b: BigInt(1000000000),
            c: BigInt("1000000000000000000000000000"),
            d: BigInt(100),
            e: BigInt(0),
            f: BigInt(4),
            g: BigInt(8),
            h: BigInt(3),
            i: BigInt(5),
            j: undefined,
            k: undefined,
            l: BigInt(11),
            m: BigInt(1000000),
            n: BigInt(1),
            o: BigInt(0),
            p: BigInt("1000000000000000000000000"),
            q: BigInt("1000000000000000"),
            r: BigInt(0),
            s: BigInt(6),
            t: BigInt(2),
            u: BigInt(4),
            v: BigInt(5),
            w: BigInt(2),
            x: BigInt(6),
            y: BigInt(20),
            z: BigInt(0),
          };
          if (typeof puzzmon !== "string") {
            return undefined;
          }
          let score = BigInt(0);
          for (const c of puzzmon) {
            const char = c.toLowerCase();
            if (char in letterToPoints) {
              const points = letterToPoints[char];
              if (points === undefined) {
                return undefined;
              }
              score += points;
            }
          }
          return score;
        },
      },
    },
  ],
  questions: [
    {
      id: "puzzmon",
      question_template: "Pick a Puzzmon: {{Puzzmon}}",
      cost: 30,
      question_content: {
        Puzzmon: ALL_PUZZMON_NAMES, // Populated locally
      },
      response_function: (id: string, parameters: Record<string, string>) => {
        const answer_template = "{{Puzzmon}} scored {{conclusion}} points.";
        const answer = getAnswer(id);
        const score = answer.task_content?.scoring_function?.(
          parameters.Puzzmon,
        );

        if (score === undefined) {
          return {
            message: fillTemplate("{{Puzzmon}} cannot be scored.", {
              Puzzmon: parameters.Puzzmon,
            }),
          };
        }

        return {
          message: fillTemplate(answer_template, {
            conclusion: score.toString(),
            Puzzmon: parameters.Puzzmon,
          }),
        };
      },
    },
  ],
  validate_submission: (
    id: string,
    submission: string,
    // supplemental_data omitted since we validate locally with full access
  ) => {
    // In local mode, 'id' is passed from the QATaskComponent/QATask logic.
    // 'id' corresponds to the answer option ID.
    const answer = getAnswer(id);
    const scoringFn = answer.task_content?.scoring_function;

    // We treat "startPuzzmons" as ALL_PUZZMON_NAMES in this static version simplification
    // or arguably we don't even need to restrict it if we just score "all" names.
    // But to find the "best" we need to score all known puzzmons.
    if (!scoringFn) return false;

    const bestPuzzmons = getBestPuzzmons(ALL_PUZZMON_NAMES, scoringFn);
    return bestPuzzmons.includes(toTitleCase(submission));
  },
  validation_cooldown: 60,
  retry_cooldown: 0,
};
